properties.body:
const selectedTabName = $ctrl.payComponentTabItemsMap.get(selectedTab);

if($ctrl.isPanelOpen) {
    const discard = await $ctrl.handlers.onSidePanelClose();
    if(!discard){
        const tabBarCtrl = angular.element(document.querySelector('.pay-component-tab-bar')).isolateScope().$ctrl;
        tabBarCtrl.selectedTab = $ctrl.uiState.payComponent.previousId;
        return;
    }
}

$ctrl.uiState.payComponent.previousId = selectedTab;
$ctrl.sidePanelVisible = false;
$ctrl.uiState.payComponent.name = selectedTabName;

$ctrl.tabConfig.worker_pay_component.columnDefaultConfig = $ctrl.workerPayComponentService.getColumnDefaults(selectedTabName);

$ctrl.helpers._resetProfileUiStateFilter();
$ctrl.loaders.loadActiveTab();

if(!$ctrl.userId) {
    return;
}

if(!$ctrl.isPanelOpen) {
    $ctrl.sidePanelVisible = false;
    $ctrl.formManagementService.onFormClose($ctrl.uiState);
    $ctrl.uiState.isViewingLegacyPaySlip = false;
    $ctrl.uiState.selectedPaySlipDetails = "";
}

$ctrl.uiState.currentTab.name = $ctrl.entityType;
$ctrl.loaders.loadActiveTab();

$ctrl.uiState.selectedRow = row;
const tableCtrl = angular.element(document.querySelector('bln-table')).isolateScope().$ctrl;
const isEditing = $ctrl.uiState.isEditingExistingEntity;
const isAdding = $ctrl.uiState.isCreatingNewEntity;
const formStatus = isEditing || isAdding;

// if ($ctrl.uiState.reselectPostUpdate) {
//     $ctrl.uiState.reselectPostUpdate = false;
//     return;
// }

if ((row && $ctrl.uiState.selectedEntity && row.Id === $ctrl.uiState.selectedEntity.Id) && !isAdding) {
    if($ctrl.sidePanelVisible && !isEditing) {
        $ctrl.sidePanelVisible = false;
        $ctrl.isPanelOpen = false;
    }

    return;
}

if (formStatus && $ctrl.isPanelOpen && !$ctrl.uiState.reselectPostUpdate) {
    if (!row && isAdding) {
        return;
    }

    const discardChanges = await $ctrl.utils.handleUnsavedChanges(formStatus);

    if (!discardChanges) {
        if (isAdding) {
            tableCtrl.gridApi.selection.clearSelectedRows();
        } else {
            const displayedData = tableCtrl?.tableConfig?.data ?? [];
            const oldIndex = displayedData.findIndex(r => r.Id === $ctrl.uiState.selectedEntity.Id);

            if (oldIndex !== -1) {
                $ctrl.utils.setSelectedBelliniTableRow(oldIndex);
            }
        }

        $ctrl.sidePanelVisible = true;
        return;
    } else {
        if (isAdding) {
            $ctrl.formManagementService.onFormClose($ctrl.uiState);
            $ctrl.sidePanelVisible = false;
            $ctrl.isPanelOpen = false;
        }
    }
}

if (!row) {
    $ctrl.uiState.selectedEntity = {};
    $ctrl.uiState.selectedEntityName = "";
    $ctrl.uiState.detailsList = [];
    $ctrl.$timeout(() => {
        $ctrl.sidePanelVisible = false;
        $ctrl.isPanelOpen = false;
    });

    if (isEditing) {
        $ctrl.formManagementService.onFormClose($ctrl.uiState);
    }
    return;
}

const currentEntityType = $ctrl.entityType;
const tabConfig = $ctrl.tabConfig[currentEntityType];

let hydratedEntity;
if($ctrl.authService.isCurrentUserAdmin) {
    hydratedEntity = await $ctrl.referenceDataService.hydrateEntity(row);
} else {
    hydratedEntity = row;
}

// Abort if the user switched tabs while hydrateEntity was in flight
if ($ctrl.entityType !== currentEntityType) {
    return;
}

// Abort if user switched rows while hydrateEntity was in flight
if($ctrl.uiState.selectedRow !== row) {
    return;
}

$ctrl.uiState.selectedEntity = hydratedEntity;
$ctrl.uiState.selectedEntityName = row?.Name ?? row?.Earning ?? row?.Benefit ?? row?.EarningCode ?? row?.PayPeriodDisplayName ?? row?.AccrualName;

let detailsSourceEntity = hydratedEntity;

// Hide extra payslip details on table view
if ($ctrl.entityType === "pay_slip" && hydratedEntity) {
    const excludedKeys = [
        "AccrualBalance",
        "BankInfo",
        "DeductionLogs",
        "EarningLogs",
        "EmploymentInfo",
        "StatutoryCompliance"
    ];

    detailsSourceEntity = Object.keys(hydratedEntity).reduce((acc, key) => {
        const isExcluded = excludedKeys.some(excludedKey => key.includes(excludedKey));
        if (!isExcluded) {
            acc[key] = hydratedEntity[key];
        }
        return acc;
    }, {});
}

$ctrl.uiState.detailsList = $ctrl.helpers._generateAndMaskDetailsList(detailsSourceEntity, tabConfig);
$ctrl.sidePanelVisible = true

if (isEditing) {
    const formObj = $ctrl[tabConfig.form];
    if (formObj) {
        $ctrl.formManagementService.onFormOpen(
            $ctrl.uiState,
            formObj,
            "edit",
            undefined,
            row
        );
    }
}

$ctrl.uiState.reselectPostUpdate = false;

if ($ctrl.uiState.isViewingLegacyPaySlip) {
    await $ctrl.handlers.onOpenFormattedPaySlipView();
}

const tableCtrl = angular.element(document.querySelector('bln-table')).isolateScope().$ctrl;

if($ctrl.uiState.isViewingLegacyPaySlip) {
    $ctrl.uiState.isViewingLegacyPaySlip = false;
    $ctrl.uiState.selectedPaySlipDetails = ""; 
    return;
}

if($ctrl.uiState.isCreatingNewEntity || $ctrl.uiState.isEditingExistingEntity) {
    const discard = await $ctrl.utils.handleUnsavedChanges($ctrl.isPanelOpen);
    if(discard) {
        if($ctrl.uiState.isCreatingNewEntity) {
            $ctrl.sidePanelVisible = false;    
        }

        $ctrl.formManagementService.onFormClose($ctrl.uiState);
        $ctrl.isPanelOpen = false;
        if($ctrl.entityType === "worker_pay_component") {
            return true;
        }
    }

    return;
}

if($ctrl.sidePanelVisible) {
    $ctrl.sidePanelVisible = false;
    $ctrl.uiState.selectedEntity = {};
    $ctrl.uiState.selectedEntityName = "";
    $ctrl.uiState.detailsList = [];

    if(tableCtrl.gridApi.selection) {
        tableCtrl.gridApi.selection.clearSelectedRows();
    }
}

if(!$ctrl.authService.isCurrentUserAdmin) {
    $ctrl.utils.toast("You do not have permission to perform this action.", "ERROR");
    console.error("Forbidden");
    return;
}

$ctrl.formManagementService.onFormOpen(
    $ctrl.uiState,
    $ctrl[$ctrl.tabConfig[$ctrl.uiState.currentTab.name].form],
    "edit",
    undefined,
    $ctrl.uiState.selectedEntity
);

$ctrl.isPanelOpen = true;

const entityType = $ctrl.entityType;
const tabStore = $ctrl.tabStore[entityType];
const tabConfig = $ctrl.tabConfig[entityType];
const limit = tabStore.limit || 25;

if (!tabStore) return;

if (entityType === "worker_pay_component") {
    tabStore.filteredData = tabStore.data;
    return;
}

const sourceData = tabStore.data || [];

if (!filterValue) {
    tabStore.filteredData = sourceData;
    tabStore.totalCount = sourceData.length;
    tabStore.currentPage = 1;
    tabStore.pageCount = Math.max(1, Math.ceil(sourceData.length / limit));
    tabStore.hasNextPage = tabStore.pageCount > 1;
    return;
}

const filterDefinitions = (tabConfig?.service?.getFilterDefinitions)
    ? tabConfig.service.getFilterDefinitions()
    : [];

const searchableKeys = filterDefinitions.length > 0
    ? filterDefinitions.map((def) => def.value)
    : Object.keys(sourceData[0] || {});

const normalizedFilter = String(filterValue).toLowerCase();

tabStore.filteredData = sourceData.filter((row) =>
    searchableKeys.some((key) => {
        const value = row[key];
        return value !== undefined && value !== null &&
            String(value).toLowerCase().includes(normalizedFilter);
    })
);

tabStore.totalCount = sourceData.length;
tabStore.currentPage = 1;
tabStore.pageCount = Math.max(1, Math.ceil(tabStore.filteredData.length / limit));
tabStore.hasNextPage = tabStore.pageCount > 1;

if ($ctrl.authService.isCurrentUserAdmin) {
    return $ctrl.tabManagementService.onPageChange(
        $ctrl.uiState, $ctrl.tabStore, $ctrl.loaders, currentPage
    );
}

// Pagination control for front end filter
const tabStore = $ctrl.tabStore[$ctrl.entityType];
if (!tabStore) return;

tabStore.previousPage = tabStore.currentPage;
tabStore.currentPage = currentPage;

if(!$ctrl.authService.isCurrentUserAdmin) {
    $ctrl.utils.toast("You do not have permission to perform this action.", "ERROR");
    console.error("Forbidden");
    return;
}

if (action === "add") {
    $ctrl.uiState.selectedEntity = null;
    $ctrl.uiState.selectedEntityName = "";

    $ctrl.formManagementService.onFormOpen(
        $ctrl.uiState,
        $ctrl[$ctrl.tabConfig[$ctrl.uiState.currentTab.name].form],
        "add",
        true
    )

    $ctrl.sidePanelVisible = true
    $ctrl.isPanelOpen = true;
    return;
}

if (action === "edit") {
    $ctrl.formManagementService.onFormOpen(
        $ctrl.uiState,
        $ctrl[$ctrl.tabConfig[$ctrl.uiState.currentTab.name].form],
        "edit",
        undefined,
        $ctrl.uiState.selectedEntity
    );

    $ctrl.isPanelOpen = true;
    return;
}

if(!$ctrl.authService.isCurrentUserAdmin) {
    $ctrl.utils.toast("You do not have permission to perform this action.", "ERROR");
    console.error("Forbidden");
    return;
}

const workerId = $ctrl.workerId;
const componentTypeName = $ctrl.uiState.payComponent.name;

if (!workerId || !componentTypeName) {
    console.error("Cannot assign components: Missing WorkerID or Component Type selection.");
    return;
}

const isEarning = componentTypeName === 'earning';
const componentClass = isEarning ? 'EARNING' : 'BENEFIT';
const foreignKey = isEarning ? 'EarningId' : 'BenefitId';
const titleCasedComponentType = isEarning ? 'Earning' : 'Benefit';

const currentList = $ctrl.tabStore['worker_pay_component']?.data || [];

// assigned rows
const assignedItems = currentList.map(item => ({
    Id: item[foreignKey],
    _linkId: item.Id,
    Name: item[titleCasedComponentType],
    [foreignKey]: item[foreignKey],
    CustomEmployeeAmount: item.CustomEmployeeAmount,
    ...(!isEarning && { CustomEmployerAmount: item.CustomEmployerAmount })
}));

const alreadyAssignedIds = assignedItems.map(x => x[foreignKey]);

// baseline filters
const commonQueryParams = [`CompanyId=${$ctrl.globalSelectedCompany.companyId}`, `Active=1`];
const exclusionQueryKey = 'Id_notin';
let preloadQueryParams = [...commonQueryParams];

if (alreadyAssignedIds.length > 0) {
    preloadQueryParams.push(`${exclusionQueryKey}=${alreadyAssignedIds.join(",")}`);
}

const mapUnassignedEntity = (e) => ({
    Id: e.Id,
    Name: e.Name,
    [foreignKey]: e.Id
});

let unassignedItems = []
let unassignedPageCount = 1;

try {
    // baseline data pull
    const res = await $ctrl.payrollApiService.get({
        entity: componentTypeName,
        query: preloadQueryParams.join("&")
    });

    const entities = res.entities ?? res ?? [];
    unassignedItems = entities.map(mapUnassignedEntity)
    unassignedPageCount = res.metadata?.pageCount ?? 1;

} catch (err) {
    console.warn(`Skipping ${componentTypeName} preload due to API error`, err);
}

const entityColumns = [{ name: "Name", valueKey: "Name", enableEditing: false }]
const amountColumns = [{ name: "Custom Employee Amount", valueKey: "CustomEmployeeAmount", enableEditing: true, type: "number" }]
if (!isEarning) {
    amountColumns.push({ name: "Custom Employer Amount", valueKey: "CustomEmployerAmount", enableEditing: true, type: "number" })
}
const totalAssignedColumns = [...entityColumns, ...amountColumns]

// call centralized helper method
return $ctrl.assignmentUtilsService.openAssignmentModal({
    title: `Assign ${titleCasedComponentType}s to Worker`,
    assigned: {
        columns: totalAssignedColumns,
        items: assignedItems
    },
    unassigned: {
        columns: [{ name: "Name", valueKey: "Name", enableEditing: false }],
        items: unassignedItems,
        totalPages: unassignedPageCount
    },
    api: {
        entity: componentTypeName,
        baseParams: commonQueryParams,
        searchParamKey: "Name_contains",
        searchProperty: "Name",
        searchPlaceholder: isEarning ? "Earning Name Contains" : "Benefit Name Contains",
        exclusionQueryKey: exclusionQueryKey,
        exclusionItemKey: "Id"
    },
    mapEntityFn: mapUnassignedEntity,
    onApply: (appliedItems) => {
        // store original data for sync
        const originalForSync = currentList.map(item => ({
            ...item,
            _linkId: item.Id
        }));

        const finalForSync = appliedItems.map(item => {
            const original = currentList.find(o =>
                o[foreignKey] === item[foreignKey] || o[foreignKey] === item.Id
            );

            return {
                ...item,
                _linkId: original ? original.Id : undefined
            };
        });

        $ctrl.payComponentAssignmentService.syncPayComponentsByPositionOrWorker(
            $ctrl.payrollApiService,
            'worker',
            workerId,
            componentClass,
            originalForSync,
            finalForSync
        ).then(() => {
            $ctrl.loaders.loadActiveTab();
        })
    }
})

if (rowData.isMasked) {
    rowData.value = rowData.originalValue;
    rowData.isMasked = false;
} else {
    rowData.value = rowData.maskedValue;
    rowData.isMasked = true;
}

const currentPaySlip = $ctrl.uiState.selectedEntity;

$ctrl.helpers._legacyGeneratePaySlipView(currentPaySlip);
$ctrl.uiState.isViewingLegacyPaySlip = true;

if(!$ctrl.authService.isCurrentUserAdmin) {
    $ctrl.utils.toast("You do not have permission to perform this action.", "ERROR");
    console.error("Forbidden");
    return;
}

const currentRequest = $ctrl.uiState.currentRequestId
const config = $ctrl.tabConfig[$ctrl.entityType];
if (!config) {
    console.error("No configuration found for current tab:", $ctrl.entityType);
    return;
}

const isCreate = $ctrl.uiState.isCreatingNewEntity;
const isUpdate = $ctrl.uiState.isEditingExistingEntity;
const entityType = $ctrl.entityType;

const method = isCreate ? "POST" : "PUT";
const formData = $ctrl[config.form];

let displayName = "Item";
if (config.getName) {
    displayName = config.getName(formData);
} else if (config.entityNameKey) {
    displayName = formData[config.entityNameKey] || "Item";
}

const additionalData = {};
if (isCreate) {
    if (config.isCompanyBound) {
        additionalData.CompanyId = $ctrl.globalSelectedCompany.companyId;
    }

    if (config.isWorkerBound && $ctrl.workerId) {
        additionalData.WorkerId = $ctrl.workerId;
    }

    if (config.isUserBound && $ctrl.userId) {
        additionalData.UserId = $ctrl.userId;
    }
}

$ctrl.uiState.isSaving = true;

await $ctrl.entityOperationsService.executeEntityOperation(
    method,
    (isUpdate) ? $ctrl.helpers._excludeFieldsOnSave(formData) : formData,
    async (result) => {
        if (isUpdate) {
            if(currentRequest !== $ctrl.uiState.currentRequestId) {
                return;
            }

            const selectedEntityId = $ctrl.uiState.selectedEntity.Id;

            const preReloadIndex = $ctrl.tabStore[$ctrl.uiState.currentTab.name].data.findIndex(entity => entity.Id === selectedEntityId);
            if (preReloadIndex === -1) {
                $ctrl.loaders.loadActiveTab();
                throw new Error(`Entity not found in table`);
            }

            const formToReset = document.querySelector('.form');
            if (formToReset) {
                formToReset.scrollTop = 0;
            }

            await $ctrl.loaders.loadActiveTab();

            // Reselect row 
            const tableRowIndex = $ctrl.tabStore[$ctrl.uiState.currentTab.name].data.findIndex(entity => entity.Id === selectedEntityId);
            if (tableRowIndex !== -1) {
                const tableCtrl = angular.element(document.querySelector('bln-table')).isolateScope().$ctrl;
                if (tableCtrl.gridApi.selection) {
                    $ctrl.$timeout(() => {
                        $ctrl.uiState.reselectPostUpdate = true;
                        $ctrl.utils.setSelectedBelliniTableRow(tableRowIndex);

                    });
                }
            }

            // Reopen panel
            $ctrl.formManagementService.onFormOpen(
                $ctrl.uiState,
                $ctrl[config.form],
                "edit",
                undefined,
                $ctrl.uiState.selectedEntity
            );

            $ctrl.isPanelOpen = true;
            $ctrl.sidePanelVisible = true;

        } else {
            $ctrl.loaders.loadActiveTab();
            $ctrl.formManagementService.onFormClose($ctrl.uiState);
            $ctrl.sidePanelVisible = false;
            $ctrl.isPanelOpen = false;
            $ctrl.utils.resetForm(formData);
        }
    },
    null,
    () => {
        $ctrl.uiState.isSaving = false;
    },
    $ctrl.entityType,
    displayName,
    $ctrl.uiState.selectedEntity,
    additionalData
);

if(!$ctrl.authService.isCurrentUserAdmin) {
    $ctrl.utils.toast("You do not have permission to perform this action.", "ERROR");
    console.error("Forbidden");
    return;
}

const entityName = $ctrl.uiState.selectedEntityName || "Item";
const entityType = $ctrl.entityType;
const entityToDelete = $ctrl.uiState.selectedEntity;

if (!entityToDelete) return;

await $ctrl.entityOperationsService.confirmDelete(entityToDelete, entityName)
    .then(confirmed => {
        if (!confirmed) return;

        $ctrl.uiState.isDeleting = true;

        return $ctrl.entityOperationsService.executeEntityOperation(
            "DELETE",
            null,
            () => {
                $ctrl.uiState.selectedEntity = null;
                $ctrl.uiState.selectedEntityName = null;
                $ctrl.sidePanelVisible = false
                $ctrl.isPanelOpen = false;

                $ctrl.loaders.loadActiveTab();
            },
            null,
            () => {
                $ctrl.uiState.isDeleting = false;
            },
            entityType,
            entityName,
            entityToDelete
        );
    });

// importScripts(["https://cdnjs.cloudflare.com/ajax/libs/html2canvas/1.4.1/html2canvas.min.js", "https://cdnjs.cloudflare.com/ajax/libs/jspdf/2.5.1/jspdf.umd.min.js"]);

const { jsPDF } = window.jspdf;
const divId = "info-panel";
const fileName = $ctrl.uiState.selectedEntity.WorkerName + " - " + $ctrl.utils.formatDate($ctrl.uiState.selectedEntity.PayPeriodStartDate).split(" ")[0].split("-")[1] + " " + $ctrl.utils.formatDate($ctrl.uiState.selectedEntity.PayPeriodStartDate).split(" ")[0].split("-")[2] + "-" + $ctrl.utils.formatDate($ctrl.uiState.selectedEntity.PayPeriodEndDate).split(" ")[0].split("-")[2] + " " + $ctrl.utils.formatDate($ctrl.uiState.selectedEntity.PayPeriodStartDate).split(" ")[0].split("-")[0];

// Bond paper dimensions in points (72 points per inch)
const BOND_PAPER_WIDTH = 8.5 * 72; // 612 points
const BOND_PAPER_HEIGHT = 11 * 72; // 792 points

// Get the div element
const divElement = document.getElementById(divId);
if (!divElement) {
    console.error(`Div with ID '${divId}' not found`);
    return;
}

// Save the original styles to restore later
const originalStyle = {
    width: divElement.style.width,
    margin: divElement.style.margin,
};

try {
    // Temporarily set the div to full width
    divElement.style.width = '100%';
    divElement.style.margin = '0 auto'; // Center the content horizontally if needed

    // Use html2canvas to capture the div as a canvas
    const canvas = await html2canvas(divElement, { scale: 2 }); // Higher scale for better resolution

    // Get the canvas dimensions
    const canvasWidth = canvas.width;
    const canvasHeight = canvas.height;

    // Calculate scale to fit the bond paper dimensions
    const scale = Math.min(BOND_PAPER_WIDTH / canvasWidth, BOND_PAPER_HEIGHT / canvasHeight);

    const imgWidth = canvasWidth * scale;
    const imgHeight = canvasHeight * scale;

    // Convert the canvas to an image
    const imgData = canvas.toDataURL('image/png');

    // Initialize jsPDF with bond paper size
    const pdf = new jsPDF({
        orientation: 'portrait',
        unit: 'pt',
        format: [BOND_PAPER_WIDTH, BOND_PAPER_HEIGHT],
    });

    // Center the image on the bond paper
    const xOffset = (BOND_PAPER_WIDTH - imgWidth) / 2;
    const yOffset = (BOND_PAPER_HEIGHT - imgHeight) / 2;

    // Add the image to the PDF
    pdf.addImage(imgData, 'PNG', xOffset, yOffset, imgWidth, imgHeight);

    // Save the PDF
    pdf.save(fileName || 'document.pdf');
} catch (error) {
    console.error('Error generating PDF:', error);
} finally {
    // Restore the original styles
    divElement.style.width = originalStyle.width;
    divElement.style.margin = originalStyle.margin;
}

if (!data) return [];

const detailsList = $ctrl.entityViewService.generateDetailsList(data);

if (tabConfig?.containsSensitiveInfo && tabConfig?.sensitiveInfoFields) {
    return $ctrl.helpers._maskSensitiveInfo(tabConfig.sensitiveInfoFields, detailsList);
}

return detailsList;

const sensitiveFieldsSet = new Set(sensitiveInfoFields);
return detailsList.map(item => {
    if (item.isSpacer || !sensitiveFieldsSet.has(item.originalKey)) {
        return item;
    }

    const strValue = String(item.value || "");
    const maskedValue = "*".repeat(strValue.length);

    return {
        ...item,
        originalValue: item.value,
        value: maskedValue, // Default to maskedValue for sensitive info
        maskedValue: maskedValue,
        isMasked: true
    };
});

$ctrl.uiState.selectedEntity = null;
$ctrl.uiState.selectedEntityName = "";

$ctrl.uiState.displayedInfo = [];
$ctrl.uiState.detailsList = [];

if (resetTabStore && $ctrl.tabStore[$ctrl.entityType]) {
    $ctrl.tabStore[$ctrl.entityType].data = [];
}

const tabConfig = $ctrl.tabConfig[entityType];
const workerId = $ctrl.workerId;
const isWorkerPayComponent = (entityType === "worker_pay_component");

let filtersToProcess = [...($ctrl.uiState.currentFilter.advancedFilters || [])];
let extraApiQuery = "";

if (isWorkerPayComponent) {
    const nameFilterIndex = filtersToProcess.findIndex(f => f.property === "Name");

    if (nameFilterIndex > -1) {
        const nameFilter = filtersToProcess[nameFilterIndex];
        filtersToProcess.splice(nameFilterIndex, 1);

        const targetSubEntity = $ctrl.uiState.payComponent.name;
        try {
            const lookupRes = await $ctrl.payrollApiService.get({
                entity: targetSubEntity,
                query: `Name_${nameFilter.operation}=${nameFilter.value}&select=Id`
            });

            const ids = (lookupRes.entities || []).map(e => e.Id);
            const foreignKey = targetSubEntity === 'earning' ? 'EarningId' : 'BenefitId';

            extraApiQuery += ids.length > 0
                ? `&${foreignKey}_in=${ids.join(',')}`
                : `&Id_eq=-1`;
        } catch (err) {
            console.warn("Failed to lookup pay component names", err);
            extraApiQuery += `&Id_eq=-1`;
        }
    }

    const componentClass = $ctrl.uiState.payComponent.name.toUpperCase();
    extraApiQuery += `&ComponentClass=${componentClass}`;
}

let apiQuery = $ctrl.filterService.buildCombinedQuery({
    advancedFilters: filtersToProcess
});

if (tabConfig?.isWorkerBound) {
    apiQuery += workerId ? `&WorkerId_eq=${workerId}` : `&Id_eq=-1`;
}

if (entityType === "worker") {
    apiQuery += workerId ? `&Id_eq=${workerId}` : `&Id_eq=-1`;
}

if (tabConfig?.containsSensitiveInfo) {
    apiQuery += "&maskSensitiveWorkerInfo=false" // Request unmasked data and just do FE masking to reduce API roundtrips
}

return apiQuery + extraApiQuery;

let msg = "Looks like there's no data here. ";

switch ($ctrl.entityType) {
    default:
        if($ctrl.authService.isCurrentUserAdmin){
            msg += "Click + to get started.";
        }

        break;
    case "worker_pay_component":
        if($ctrl.authService.isCurrentUserAdmin){
            msg += "Click manage assignments button to get started.";
        }

        break;
    case "attendance_summary":
        if($ctrl.authService.isCurrentUserAdmin){
            msg += "Go to Attendance Summary page to get started.";
        }

        break;
    case "pay_slip":
        if($ctrl.authService.isCurrentUserAdmin){
            msg += "Go to Payroll Processing page to get started.";
        }

        break;
}

return msg;

$ctrl.uiState.currentFilter.advancedFilters = [];
$ctrl.uiState.currentFilter.chips = [];
$ctrl.uiState.currentFilter.chipMap = [];
$ctrl.uiState.currentFilter.currentFilterString = "";
$ctrl.uiState.currentFilter.usingAdvancedFilters = false;

if (!row) {
    $ctrl.uiState.selectedPaySlipDetails = "";
    return;
}

$ctrl.uiState.selectedEntity = row;
$ctrl.uiState.selectedEntityName = row.PayPeriodDisplayName;

let htmlContent = "";

function appendHTML(html) {
    htmlContent += html;
}

for (const [key, value] of Object.entries(row)) {
    if (key.startsWith("$$") || (isExcludedKey(key, value) && key !== "PayPeriodRate")) continue;

    switch (key) {
        case "PayPeriodRate":
            appendHTML(buildPayPeriodRate(row.Frequency, value, row));
            break;
        case "WorkerName":
            appendHTML(`<div>${value}</div>`);
            break;
        case "BankInfo":
            Object.entries(value).forEach(([k, v]) => {
                if (k !== "Id") appendHTML(buildGeneralDetails(k, v));
            });
            break;
        case "CreatedDate":
            return finalizeView();
        case "AccrualBalance":
            if (value && value.length > 0) {
                appendHTML(buildSectionTitle("Leave Credits"));
                appendHTML(buildAccrualBalances(value, row));
            }
            break;
        case "GrossPay":
        case "TotalDeductions":
        case "NetPay":
            appendHTML(buildTotals(key, value, row));
            break;
        default:
            if (isStatutoryCompliance(key)) {
                appendHTML(buildStatutoryCompliance(value));
            } else if (isPayComponent(key)) {
                appendHTML(buildPayComponents(key, value, row));
            } else {
                appendHTML(buildGeneralDetails(key, value));
            }
    }
}

function finalizeView() {
    $ctrl.uiState.selectedPaySlipDetails = htmlContent;
}

finalizeView();

// --- Helper Functions (Pure functions returning HTML strings) ---
function isExcludedKey(key, value) {
    const excludedKeys = [
        "Id", "PayPeriod", "Payroll", "Department", "Position",
        "Frequency", "GrossTaxable", "GrossNonTaxable", "PreTaxDeductions", "NetTaxable", "Taxes",
        "PostTaxDeductions", "Ytd"
    ];
    return excludedKeys.some(item => key.includes(item)) || value === undefined || value === null;
}

function isStatutoryCompliance(key) {
    return key.includes("StatutoryCompliance");
}

function isPayComponent(key) {
    const relevantKeywords = ["Earning", "Deduction"];
    return relevantKeywords.some(kw => key.includes(kw) && !key.includes("Tax") && !key.includes("Total"));
}

function formatFrequency(frequency) {
    if (!frequency) return "";
    return frequency
        .toLowerCase()
        .split(/[-\s]/)
        .map(word => word.charAt(0).toUpperCase() + word.slice(1))
        .join(frequency.includes("-") ? "-" : " ");
}

function formatCurrency(amount, fractionDigits = 2, isCurrency = true, currency) {
    const symbol = isCurrency && currency?.CurrencySymbol ? currency.CurrencySymbol : '';
    const precision = currency?.CurrencyPrecision || fractionDigits;
    const formattedAmount = Number(amount || 0).toLocaleString("en-US", {
        minimumFractionDigits: precision,
        maximumFractionDigits: precision
    });
    return `${symbol} ${formattedAmount}`.trim();
}

