        html += buildPayComponentCategory("Pre-tax", components.filter(c => c.Type === "PRETAX"), row.PreTaxDeductions, currency);
        html += buildTempNetTaxable("Net Taxable", [{ Name: "Gross Taxable", EmployeeAmount: row.GrossTaxable }, { Name: "Pre-tax Deductions", EmployeeAmount: -Math.abs(row.PreTaxDeductions) }], row.NetTaxable, currency);
        html += buildPayComponentCategory("Tax", components.filter(c => c.ComponentClass === "TAX"), row.Taxes, currency);
        html += buildPayComponentCategory("Post-tax", components.filter(c => c.Type === "POSTTAX"), row.PostTaxDeductions, currency);
    } else {
        const nonTaxable = components.filter(comp => !comp.IsTaxable);
        const taxable = components.filter(comp => comp.IsTaxable);
        html += buildPayComponentCategory("Non-taxable", nonTaxable, row.GrossNonTaxable, currency);
        html += buildPayComponentCategory("Taxable", taxable, row.GrossTaxable, currency);
    }
    return html;
}

