const { page = tabStore.currentPage, currentRequestId } = params;

// Fetch limit for front end filtering
const FETCH_ALL_LIMIT = 1000;
const apiPage = (isWorkerPayComponent || isUsrAdmin)  ? (params.page ?? tabStore.currentPage) : 1;

try {
    const serviceOptions = {
        entityType: entityType,
        query: query,
        columnDefs: tabConfig?.columnDefaultConfig ?? [],
        customEntityKey: tabConfig?.customEntityKey,
        page: apiPage,
        limit: isUsrAdmin ? tabStore.limit : FETCH_ALL_LIMIT,
