            entity: `pay_slip/worker/${workerId}`,
            limit: limit,
            offset: offset,
            query: "maskSensitiveWorkerInfo=false",
            customEntityKey: "pay_slip"
        });

        const payslips = res.entities ?? res.pay_slip ?? res ?? [];
        const foundPayslip = payslips.find(p => p.Id === targetPaySlipId);

        if (foundPayslip) {
            return foundPayslip;
        }

        if (res.metadata) { // Since we do not have metadata yet on that endpoint, it will skip this.
            hasNextPage = res.metadata.hasNextPage;
            // Alternatively: hasNextPage = offset + limit < res.metadata.totalCount;
        } else {
            hasNextPage = payslips.length === limit;
        }

        offset += limit;
    }

    // In case the Pay Slip is not found, though unlikely.
    console.warn(`Detailed Payslip ${targetPaySlipId} not found in legacy endpoint for Worker ${workerId}.`);
    return null;

} catch (err) {
    console.error("Failed to fetch detailed legacy payslip", err);
    $ctrl.utils.toast("Failed to load detailed payslip information.", "ERROR");
    return null;
} finally {
    $ctrl.uiState.isLoadingDetails = false;
